begin;
insert into public.permissions(code,description)values('events.operations.manage','Manage event logistics, private eligibility, tickets and physical payment checks'),('events.checkin','Verify event-bound tickets and explicitly record attendance');
insert into public.role_permissions select r.id,p.id from public.roles r cross join public.permissions p where r.code in('platform_owner','operations_lead')and p.code in('events.operations.manage','events.checkin');
create table business_private.event_assets(id uuid primary key default gen_random_uuid(),path text not null unique check(path ~ '^/event-media/[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp|avif)$'),alt text not null check(length(btrim(alt))between 1 and 240),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),rights_reference text not null,approved boolean not null default false);
create table business_private.events(id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'and length(slug)<=80),draft jsonb not null,public_content jsonb,operations jsonb,visibility text not null default 'private'check(visibility in('public','private')),registration_open boolean not null default false,lifecycle text not null default 'planned'check(lifecycle in('planned','completed','cancelled')),version int not null default 1,intake_version int not null default 1,published_at timestamptz,updated_at timestamptz not null default now());
create table business_private.event_invites(id uuid primary key,event_id uuid not null references business_private.events(id)on delete restrict,email text not null,token_hash bytea not null unique check(octet_length(token_hash)=32),code_hash bytea not null check(octet_length(code_hash)=32),expires_at timestamptz not null,revoked_at timestamptz,access_hash bytea unique,access_expires_at timestamptz,evidence text not null,version int not null default 1,created_at timestamptz not null default now(),unique(id,event_id));
create unique index event_one_active_invite on business_private.event_invites(event_id,email)where revoked_at is null;
create table business_private.event_registrations(id uuid primary key default gen_random_uuid(),event_id uuid not null references business_private.events(id)on delete restrict,invite_id uuid,reference text not null unique check(reference ~ '^BWE-[a-f0-9]{32}$'),identity_hash bytea not null check(octet_length(identity_hash)=32),idempotency_hash bytea not null unique check(octet_length(idempotency_hash)=32),payload_hash bytea not null check(octet_length(payload_hash)=32),receipt_hash bytea not null unique check(octet_length(receipt_hash)=32),portal_code_hash bytea,receipt_expires_at timestamptz not null,full_name text not null,email text not null,whatsapp text,answers jsonb not null,questions jsonb not null,event_snapshot jsonb not null,status text not null check(status in('confirmed','waitlisted','cancelled')),fee_required boolean not null,fee_xaf bigint not null,consent_version text not null check(consent_version='event-registration-v1'),version int not null default 1,created_at timestamptz not null default now(),unique(event_id,identity_hash),unique(id,event_id),foreign key(invite_id,event_id)references business_private.event_invites(id,event_id)on delete restrict);
create table business_private.event_payment_checks(sequence bigint generated always as identity unique,id uuid primary key default gen_random_uuid(),registration_id uuid not null references business_private.event_registrations(id)on delete restrict,confirmed boolean not null,amount_xaf bigint not null check(amount_xaf>=0),evidence text not null,actor_id uuid references auth.users(id)on delete set null,created_at timestamptz not null default now());
create table business_private.event_tickets(id uuid primary key,registration_id uuid not null,event_id uuid not null,reference text not null unique check(reference ~ '^BWT-[a-f0-9]{32}$'),version int not null check(version>0),token_hash bytea not null unique check(octet_length(token_hash)=32),snapshot jsonb not null,state text not null default 'issued'check(state in('issued','revoked')),issued_at timestamptz not null default now(),actor_id uuid references auth.users(id)on delete set null,foreign key(registration_id,event_id)references business_private.event_registrations(id,event_id)on delete restrict,unique(registration_id,version));
create unique index event_one_issued_ticket on business_private.event_tickets(registration_id)where state='issued';
create table business_private.event_attendance(registration_id uuid primary key,event_id uuid not null,ticket_id uuid not null references business_private.event_tickets(id)on delete restrict,actor_id uuid references auth.users(id)on delete set null,checked_at timestamptz not null default now(),foreign key(registration_id,event_id)references business_private.event_registrations(id,event_id)on delete restrict);
create table business_private.event_buckets(scope text not null,key_hash bytea not null check(octet_length(key_hash)=32),window_start timestamptz not null,attempts int not null check(attempts>0),primary key(scope,key_hash,window_start));
revoke all on business_private.event_assets,business_private.events,business_private.event_invites,business_private.event_registrations,business_private.event_payment_checks,business_private.event_tickets,business_private.event_attendance,business_private.event_buckets from public,anon,authenticated,service_role;
do $$declare t text;begin foreach t in array array['event_assets','events','event_invites','event_registrations','event_payment_checks','event_tickets','event_attendance','event_buckets']loop execute format('alter table business_private.%I enable row level security',t);execute format('create policy %I on business_private.%I as restrictive for all to authenticated using((select app_private.has_aal2_session()))with check((select app_private.has_aal2_session()))',t||'_mfa',t);end loop;end;$$;
create function business_private.valid_event_copy(d jsonb)returns boolean language plpgsql stable set search_path=''as $$declare x jsonb;begin
 if d is null or jsonb_typeof(d)<>'object'or not d ?& array['title','description','category','posterId','speakers','schedule','recap']or(d-array['title','description','category','posterId','speakers','schedule','recap'])<>'{}'then return false;end if;
 if jsonb_typeof(d->'title')is distinct from'string'or not business_private.project_text(d->>'title',1,180)or jsonb_typeof(d->'description')is distinct from'string'or not business_private.project_text(d->>'description',1,8000)or jsonb_typeof(d->'category')is distinct from'string'or not business_private.project_text(d->>'category',1,80)or jsonb_typeof(d->'recap')is distinct from'string'or not business_private.project_text(d->>'recap',0,8000)then return false;end if;
 if d->'posterId'<>'null'::jsonb and not exists(select from business_private.event_assets where id=(d->>'posterId')::uuid and approved)then return false;end if;
 if jsonb_typeof(d->'speakers')is distinct from'array'or jsonb_array_length(d->'speakers')>20 or jsonb_typeof(d->'schedule')is distinct from'array'or jsonb_array_length(d->'schedule')>30 then return false;end if;
 for x in select * from jsonb_array_elements(d->'speakers')loop if jsonb_typeof(x)<>'object'or not x ?& array['name','topic']or(x-array['name','topic'])<>'{}'or jsonb_typeof(x->'name')is distinct from'string'or not business_private.project_text(x->>'name',1,120)or jsonb_typeof(x->'topic')is distinct from'string'or not business_private.project_text(x->>'topic',0,240)then return false;end if;end loop;
 for x in select * from jsonb_array_elements(d->'schedule')loop if jsonb_typeof(x)<>'object'or not x ?& array['time','label']or(x-array['time','label'])<>'{}'or jsonb_typeof(x->'time')is distinct from'string'or not business_private.project_text(x->>'time',1,80)or jsonb_typeof(x->'label')is distinct from'string'or not business_private.project_text(x->>'label',1,240)then return false;end if;end loop;return true;exception when invalid_text_representation or invalid_parameter_value then return false;end;$$;
create function business_private.valid_event_operations(d jsonb)returns boolean language plpgsql stable set search_path=''as $$declare k text;s timestamptz;e timestamptz;begin
 if d is null or jsonb_typeof(d)<>'object'or not d ?& array['format','startAt','endAt','timeZone','venue','platform','joiningUrl','regOpensAt','regClosesAt','capacity','feeClass','feeXaf','paymentInstructions','questions']or(d-array['format','startAt','endAt','timeZone','venue','platform','joiningUrl','regOpensAt','regClosesAt','capacity','feeClass','feeXaf','paymentInstructions','questions'])<>'{}'then return false;end if;
 if d->>'format' is null or d->>'format'not in('online','physical','hybrid')or d->>'feeClass'is null or d->>'feeClass'not in('free','paid')or not exists(select from pg_timezone_names where name=d->>'timeZone')or jsonb_typeof(d->'platform')is distinct from'string'or not business_private.project_text(d->>'platform',0,240)then return false;end if;
 foreach k in array array['startAt','endAt']loop if jsonb_typeof(d->k)is distinct from'string'or d->>k !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d{1,3})?Z$'then return false;end if;end loop;s:=(d->>'startAt')::timestamptz;e:=(d->>'endAt')::timestamptz;if s>=e or not isfinite(s)or not isfinite(e)then return false;end if;
 if not business_private.valid_program_operations(jsonb_build_object('duration','','location',d->'venue','mode',d->'format','opensAt',d->'regOpensAt','closesAt',d->'regClosesAt','capacity',d->'capacity','feeXaf',d->'feeXaf','feeInstructions',d->'paymentInstructions'))or not business_private.valid_program_questions(d->'questions')then return false;end if;
 if d->>'format'in('physical','hybrid')and length(btrim(d->>'venue'))=0 then return false;end if;
 if(d->>'feeClass'='paid'and coalesce((d->>'feeXaf')::bigint,0)<1)or(d->>'feeClass'='free'and coalesce((d->>'feeXaf')::bigint,0)<>0)then return false;end if;
 if(d->>'regOpensAt')::timestamptz>=e or(d->>'regClosesAt')::timestamptz>e then return false;end if;
 return d->'joiningUrl'='null'::jsonb or(jsonb_typeof(d->'joiningUrl')='string'and length(d->>'joiningUrl')<=2048 and d->>'joiningUrl'~'^https://([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}([/?#][^[:space:]<>]*)?$');exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then return false;end;$$;
create function business_private.event_availability(e business_private.events)returns text language sql stable set search_path=''as $$select case when e.public_content is null or not e.registration_open or e.lifecycle<>'planned'or e.operations is null then'closed'when(e.operations->>'endAt')::timestamptz<=now()then'ended'when(e.operations->>'regOpensAt')::timestamptz>now()then'not_yet_open'when(e.operations->>'regClosesAt')::timestamptz<=now()then'closed'when e.operations->>'capacity'is not null and(select count(*)from business_private.event_registrations where event_id=e.id and status='confirmed')>=(e.operations->>'capacity')::int then'waitlist'else'accepting'end$$;
create function business_private.event_view(e business_private.events,private_access boolean default false)returns jsonb language sql stable set search_path=''as $$select e.public_content||jsonb_build_object('id',e.id,'slug',e.slug,'visibility',e.visibility,'lifecycle',e.lifecycle,'intakeVersion',e.intake_version,'operations',e.operations-'joiningUrl','availability',business_private.event_availability(e),'isPast',(e.operations->>'endAt')::timestamptz<=now(),'poster',case when e.visibility='public'then(select jsonb_build_object('id',id,'path',path,'alt',alt)from business_private.event_assets where id=(e.public_content->>'posterId')::uuid and approved)else null end)$$;
create function public.list_public_events()returns jsonb language sql stable security definer set search_path=''as $$select coalesce(jsonb_agg(business_private.event_view(e)order by(e.operations->>'startAt')::timestamptz,e.id),'[]'::jsonb)from business_private.events e where visibility='public'and public_content is not null$$;
create function public.get_public_event(p_slug text)returns jsonb language sql stable security definer set search_path=''as $$select business_private.event_view(e)from business_private.events e where slug=p_slug and visibility='public'and public_content is not null$$;
create function public.list_staff_events(p_scanner boolean default false)returns jsonb language plpgsql stable security definer set search_path=''as $$begin
 if p_scanner then perform business_private.require_permission('events.checkin');return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',draft->>'title','lifecycle',lifecycle,'format',operations->>'format','startAt',operations->>'startAt','endAt',operations->>'endAt','timeZone',operations->>'timeZone')order by updated_at desc),'[]'::jsonb)from business_private.events);end if;
 if not app_private.has_aal2_session()or not(app_private.has_permission('content.read')or app_private.has_permission('events.operations.manage'))then raise exception'Access denied'using errcode='42501';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'slug',e.slug,'draft',e.draft,'published',e.public_content is not null,'version',e.version,'visibility',e.visibility,'lifecycle',e.lifecycle,'registrationOpen',e.registration_open,'intakeVersion',e.intake_version,'operations',case when app_private.has_permission('events.operations.manage')then e.operations else null end)||case when app_private.has_permission('registrations.read')then jsonb_build_object('confirmedCount',(select count(*)from business_private.event_registrations where event_id=e.id and status='confirmed'),'waitlistCount',(select count(*)from business_private.event_registrations where event_id=e.id and status='waitlisted'),'attendanceCount',(select count(*)from business_private.event_attendance where event_id=e.id))else'{}'::jsonb end order by e.updated_at desc,e.id),'[]'::jsonb)from business_private.events e);end;$$;
create function public.list_event_assets()returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('content.read');return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'path',path,'alt',alt)),'[]'::jsonb)from business_private.event_assets where approved);end;$$;
create function public.save_event_copy(p_id uuid,p_version int,p_slug text,p_copy jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare target uuid;begin perform business_private.require_permission('content.read');if p_slug is null or length(p_slug)>80 or p_slug !~'^[a-z0-9]+(-[a-z0-9]+)*$'or not business_private.valid_event_copy(p_copy)then raise exception'Invalid event copy'using errcode='22023';end if;
 if p_id is null then perform business_private.require_permission('content.create');if p_version is distinct from 0 then raise exception'Event changed'using errcode='PT409';end if;insert into business_private.events(slug,draft)values(p_slug,p_copy)returning id into target;
 else perform business_private.require_permission('content.update');update business_private.events set draft=p_copy,version=version+1,updated_at=now()where id=p_id and version=p_version and slug=p_slug returning id into target;if not found then raise exception'Event changed or slug immutable'using errcode='PT409';end if;end if;insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'event.copy_saved','event',target::text);return target;exception when unique_violation then raise exception'Slug unavailable'using errcode='PT409';end;$$;
create function public.configure_event(p_id uuid,p_version int,p_ops jsonb,p_visibility text,p_open boolean,p_lifecycle text,p_attested boolean)returns void language plpgsql security definer set search_path=''as $$declare e business_private.events;begin perform business_private.require_permission('events.operations.manage');select * into e from business_private.events where id=p_id for update;if not found or e.version is distinct from p_version then raise exception'Event changed'using errcode='PT409';end if;
 if p_attested is distinct from true or p_open is null or p_visibility is null or p_visibility not in('public','private')or p_lifecycle is null or p_lifecycle not in('planned','completed','cancelled')or not business_private.valid_event_operations(p_ops)or(p_open and(e.public_content is null or p_lifecycle<>'planned'))then raise exception'Approved event configuration required'using errcode='22023';end if;
 if e.lifecycle<>'planned'and p_lifecycle<>e.lifecycle then raise exception'Terminal event lifecycle'using errcode='22023';end if;if p_lifecycle='completed'and(p_ops->>'endAt')::timestamptz>now()then raise exception'Event has not ended'using errcode='22023';end if;
 if(exists(select from business_private.event_invites where event_id=p_id)or exists(select from business_private.event_registrations where event_id=p_id))and e.visibility<>p_visibility then raise exception'Visibility locked after eligibility grants or registrations'using errcode='22023';end if;
 if exists(select from business_private.event_registrations where event_id=p_id)and(e.operations-array['questions','regOpensAt','regClosesAt','capacity','joiningUrl'])is distinct from(p_ops-array['questions','regOpensAt','regClosesAt','capacity','joiningUrl'])then raise exception'Ticket logistics and fee terms locked after registrations'using errcode='22023';end if;
 if p_visibility='private'and((e.public_content->>'posterId')is not null)then raise exception'Private event public posters prohibited'using errcode='22023';end if;
 if p_ops->>'capacity'is not null and(p_ops->>'capacity')::int<(select count(*)from business_private.event_registrations where event_id=p_id and status='confirmed')then raise exception'Capacity below confirmed registrations'using errcode='22023';end if;
 update business_private.events set operations=p_ops,visibility=p_visibility,registration_open=p_open,lifecycle=p_lifecycle,version=version+1,intake_version=intake_version+1,updated_at=now()where id=p_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.configured','event',p_id::text,jsonb_build_object('visibility',p_visibility,'lifecycle',p_lifecycle,'open',p_open));end;$$;
create function public.publish_event(p_id uuid,p_version int,p_published boolean)returns void language plpgsql security definer set search_path=''as $$declare e business_private.events;begin perform business_private.require_permission('content.read');perform business_private.require_permission('content.publish');select * into e from business_private.events where id=p_id for update;if not found or e.version is distinct from p_version then raise exception'Event changed'using errcode='PT409';end if;
 if p_published is null or(p_published and(not business_private.valid_event_copy(e.draft)or not business_private.valid_event_operations(e.operations)or(e.visibility='private'and e.draft->'posterId'<>'null'::jsonb)))then raise exception'Complete approved logistics before publication'using errcode='22023';end if;update business_private.events set public_content=case when p_published then draft else null end,published_at=case when p_published then coalesce(published_at,now())else published_at end,registration_open=case when p_published then registration_open else false end,version=version+1,intake_version=intake_version+1,updated_at=now()where id=p_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.publication_changed','event',p_id::text,jsonb_build_object('published',p_published));end;$$;
create function business_private.event_budget(p_scope text,p_hash text,p_limit int)returns void language plpgsql set search_path=''as $$declare n int;begin if p_hash is null or p_hash !~'^[a-f0-9]{64}$'then raise exception'Invalid quota';end if;insert into business_private.event_buckets(scope,key_hash,window_start,attempts)values(p_scope,decode(p_hash,'hex'),date_trunc('hour',clock_timestamp()),1)on conflict(scope,key_hash,window_start)do update set attempts=business_private.event_buckets.attempts+1 where business_private.event_buckets.attempts<p_limit returning attempts into n;if n is null then raise exception'Event request unavailable';end if;end;$$;
create function public.create_event_invite(p_id uuid,p_event uuid,p_version int,p_email text,p_token_hex text,p_code_hex text,p_expires timestamptz,p_evidence text)returns void language plpgsql security definer set search_path=''as $$declare e business_private.events;begin perform business_private.require_permission('events.operations.manage');perform business_private.require_permission('registrations.read');perform business_private.require_permission('registrations.manage');select * into e from business_private.events where id=p_event for update;
 if not found or e.version is distinct from p_version then raise exception'Event changed'using errcode='PT409';end if;if e.visibility<>'private'or e.public_content is null or e.lifecycle<>'planned'or p_id is null or p_email is null or p_email<>lower(btrim(p_email))or length(p_email)>254 or p_email !~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or p_token_hex is null or p_token_hex !~'^[a-f0-9]{64}$'or p_code_hex is null or p_code_hex !~'^[a-f0-9]{64}$'or p_expires is null or p_expires<=now()or p_expires>(e.operations->>'endAt')::timestamptz+interval'7 days' or not business_private.project_text(p_evidence,1,240)then raise exception'Verified private eligibility required'using errcode='22023';end if;
 insert into business_private.event_invites(id,event_id,email,token_hash,code_hash,expires_at,evidence)values(p_id,p_event,p_email,decode(p_token_hex,'hex'),decode(p_code_hex,'hex'),p_expires,p_evidence);insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.invite_created','event_invite',p_id::text,jsonb_build_object('eventId',p_event));exception when unique_violation then raise exception'Active invitation already exists'using errcode='PT409';end;$$;
create function public.revoke_event_invite(p_id uuid,p_version int)returns void language plpgsql security definer set search_path=''as $$declare target uuid;begin perform business_private.require_permission('events.operations.manage');perform business_private.require_permission('registrations.manage');select event_id into target from business_private.event_invites where id=p_id;perform 1 from business_private.events where id=target for update;update business_private.event_invites set revoked_at=now(),access_hash=null,access_expires_at=null,version=version+1 where id=p_id and version=p_version and revoked_at is null;if not found then raise exception'Invitation changed'using errcode='PT409';end if;update business_private.event_tickets set state='revoked'where registration_id in(select id from business_private.event_registrations where invite_id=p_id)and state='issued';insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'event.invite_revoked','event_invite',p_id::text);end;$$;
create function public.list_event_invites(p_event uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('events.operations.manage');perform business_private.require_permission('registrations.read');return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'email',email,'expiresAt',expires_at,'revoked',revoked_at is not null,'version',version)order by created_at desc),'[]'::jsonb)from business_private.event_invites where event_id=p_event);end;$$;
create function public.claim_private_event(p_token_hex text,p_code_hex text,p_email text,p_access_hex text,p_global_hex text,p_invite_budget_hex text)returns uuid language plpgsql security definer set search_path=''as $$declare i business_private.event_invites;begin perform pg_advisory_xact_lock(42046,1);perform business_private.event_budget('claim_global',p_global_hex,60);perform business_private.event_budget('claim_invite',p_invite_budget_hex,5);
 if p_token_hex is null or p_token_hex !~'^[a-f0-9]{64}$'or p_code_hex is null or p_code_hex !~'^[a-f0-9]{64}$'or p_access_hex is null or p_access_hex !~'^[a-f0-9]{64}$'then return null;end if;
 select * into i from business_private.event_invites where token_hash=decode(p_token_hex,'hex')and code_hash=decode(p_code_hex,'hex')and email=lower(btrim(p_email))and revoked_at is null and expires_at>now()for update;if not found or not exists(select from business_private.events where id=i.event_id and visibility='private'and public_content is not null and lifecycle<>'cancelled')then return null;end if;
 update business_private.event_invites set access_hash=decode(p_access_hex,'hex'),access_expires_at=least(expires_at,now()+interval'15 minutes')where id=i.id;return i.id;end;$$;
create function business_private.event_guest(p_id uuid,p_access_hex text)returns business_private.event_invites language plpgsql stable set search_path=''as $$declare i business_private.event_invites;begin if p_access_hex is null or p_access_hex !~'^[a-f0-9]{64}$'then raise exception'Access unavailable'using errcode='42501';end if;select * into i from business_private.event_invites where id=p_id and access_hash=decode(p_access_hex,'hex')and access_expires_at>now()and expires_at>now()and revoked_at is null;if not found then raise exception'Access unavailable'using errcode='42501';end if;return i;end;$$;
create function public.read_private_event(p_invite uuid,p_access_hex text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare i business_private.event_invites;e business_private.events;begin i:=business_private.event_guest(p_invite,p_access_hex);select * into e from business_private.events where id=i.event_id and visibility='private'and public_content is not null;if not found then raise exception'Event unavailable'using errcode='42501';end if;return business_private.event_view(e,true)||jsonb_build_object('verifiedEmail',i.email);end;$$;
create function public.submit_event_registration(p_payload jsonb,p_reference text,p_identity_hex text,p_idempotency_hex text,p_payload_hex text,p_receipt_hex text,p_global_hex text,p_email_hex text,p_event_hex text,p_invite uuid default null,p_access_hex text default null)returns void language plpgsql security definer set search_path=''as $$declare e business_private.events;r business_private.event_registrations;i business_private.event_invites;s text;k text;target uuid;begin
 if p_payload is null or jsonb_typeof(p_payload)<>'object'or not p_payload ?& array['eventId','intakeVersion','fullName','email','whatsapp','answers','consent','consentVersion']or(p_payload-array['eventId','intakeVersion','fullName','email','whatsapp','answers','consent','consentVersion'])<>'{}'or pg_column_size(p_payload)>35000 or p_payload->'consent'is distinct from'true'::jsonb or(p_payload->>'consentVersion')is distinct from'event-registration-v1'or jsonb_typeof(p_payload->'fullName')is distinct from'string'or not business_private.project_text(p_payload->>'fullName',1,160)or jsonb_typeof(p_payload->'email')is distinct from'string'or length(p_payload->>'email')>254 or p_payload->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or jsonb_typeof(p_payload->'whatsapp')not in('string','null')or(p_payload->>'whatsapp'is not null and p_payload->>'whatsapp'!~'^\+[1-9][0-9]{6,14}$')or p_reference is null or p_reference!~'^BWE-[a-f0-9]{32}$'then raise exception'Invalid registration'using errcode='22023';end if;
 foreach k in array array[p_identity_hex,p_idempotency_hex,p_payload_hex,p_receipt_hex]loop if k is null or k!~'^[a-f0-9]{64}$'then raise exception'Invalid registration key'using errcode='22023';end if;end loop;perform pg_advisory_xact_lock(42046,1);perform business_private.event_budget('registration_global',p_global_hex,100);perform business_private.event_budget('registration_email',p_email_hex,3);perform business_private.event_budget('registration_event',p_event_hex,60);
 select * into e from business_private.events where id=(p_payload->>'eventId')::uuid for update;if not found then raise exception'Registration unavailable'using errcode='22023';end if;
 if e.visibility='private'then i:=business_private.event_guest(p_invite,p_access_hex);if i.event_id<>e.id or i.email<>lower(btrim(p_payload->>'email'))then raise exception'Eligibility mismatch'using errcode='42501';end if;else if p_invite is not null then raise exception'Unexpected invitation'using errcode='22023';end if;end if;
 select * into r from business_private.event_registrations where idempotency_hash=decode(p_idempotency_hex,'hex');if found then if r.payload_hash<>decode(p_payload_hex,'hex')or r.event_id<>e.id then raise exception'Conflicting registration'using errcode='22023';end if;return;end if;
 s:=business_private.event_availability(e);if s not in('accepting','waitlist')or(e.intake_version::text is distinct from p_payload->>'intakeVersion')or not business_private.valid_program_answers(p_payload->'answers',e.operations->'questions')then raise exception'Registration unavailable'using errcode='22023';end if;
 insert into business_private.event_registrations(event_id,invite_id,reference,identity_hash,idempotency_hash,payload_hash,receipt_hash,receipt_expires_at,full_name,email,whatsapp,answers,questions,event_snapshot,status,fee_required,fee_xaf,consent_version)
 values(e.id,case when e.visibility='private'then i.id else null end,p_reference,decode(p_identity_hex,'hex'),decode(p_idempotency_hex,'hex'),decode(p_payload_hex,'hex'),decode(p_receipt_hex,'hex'),(e.operations->>'endAt')::timestamptz+interval'7 days',btrim(p_payload->>'fullName'),lower(btrim(p_payload->>'email')),p_payload->>'whatsapp',p_payload->'answers',e.operations->'questions',e.public_content||jsonb_build_object('operations',e.operations-'joiningUrl','visibility',e.visibility),case when s='waitlist'then'waitlisted'else'confirmed'end,e.operations->>'feeClass'='paid',coalesce((e.operations->>'feeXaf')::bigint,0),'event-registration-v1')on conflict(event_id,identity_hash)do nothing returning id into target;
 if target is not null then insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(null,'event.registered','event_registration',target::text,jsonb_build_object('eventId',e.id,'waiting',s='waitlist'));end if;end;$$;
create function public.authorize_event_portal(p_id uuid,p_version int,p_code_hex text,p_evidence text)returns void language plpgsql security definer set search_path=''as $$begin perform business_private.require_permission('registrations.read');perform business_private.require_permission('registrations.manage');perform business_private.require_permission('events.operations.manage');if p_code_hex is null or p_code_hex!~'^[a-f0-9]{64}$'or not business_private.project_text(p_evidence,1,240)then raise exception'Independent recipient verification required'using errcode='22023';end if;update business_private.event_registrations set portal_code_hash=decode(p_code_hex,'hex'),version=version+1 where id=p_id and version=p_version and status<>'cancelled';if not found then raise exception'Registration changed'using errcode='PT409';end if;insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'event.portal_authorized','event_registration',p_id::text);end;$$;
create function business_private.event_paid(r business_private.event_registrations)returns boolean language sql stable set search_path=''as $$select not r.fee_required or coalesce((select confirmed from business_private.event_payment_checks where registration_id=r.id order by sequence desc limit 1),false)$$;
create function business_private.event_eligible(r business_private.event_registrations)returns boolean language sql stable set search_path=''as $$select r.status='confirmed'and business_private.event_paid(r)and(r.invite_id is null or exists(select from business_private.event_invites where id=r.invite_id and event_id=r.event_id and revoked_at is null))and exists(select from business_private.events where id=r.event_id and lifecycle<>'cancelled'and public_content is not null)$$;
create function public.list_event_registrations(p_event uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('registrations.read');return(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'reference',r.reference,'name',r.full_name,'email',r.email,'whatsapp',r.whatsapp,'answers',r.answers,'questions',r.questions,'status',r.status,'version',r.version,'paid',business_private.event_paid(r),'portalAuthorized',r.portal_code_hash is not null,'feeRequired',r.fee_required,'feeXaf',r.fee_xaf,'createdAt',r.created_at,'ticket',(select jsonb_build_object('id',id,'reference',reference,'version',version,'state',state)from business_private.event_tickets where registration_id=r.id order by version desc limit 1),'ticketHistory',(select coalesce(jsonb_agg(jsonb_build_object('reference',reference,'version',version,'state',state)order by version),'[]'::jsonb)from business_private.event_tickets where registration_id=r.id),'checkedIn',exists(select from business_private.event_attendance where registration_id=r.id))order by r.created_at,r.id),'[]'::jsonb)from business_private.event_registrations r where event_id=p_event);end;$$;
create function public.change_event_registration(p_id uuid,p_version int,p_action text,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare r business_private.event_registrations;e business_private.events;begin perform business_private.require_permission('registrations.read');perform business_private.require_permission('registrations.manage');perform business_private.require_permission('events.operations.manage');select * into r from business_private.event_registrations where id=p_id;if not found then raise exception'Registration unavailable';end if;select * into e from business_private.events where id=r.event_id for update;select * into r from business_private.event_registrations where id=p_id for update;if r.version is distinct from p_version then raise exception'Registration changed'using errcode='PT409';end if;
 if not business_private.project_text(p_reason,1,240)or exists(select from business_private.event_attendance where registration_id=r.id)then raise exception'Review attendance or reason before changing registration'using errcode='22023';end if;
 if p_action='promote'and r.status='waitlisted'and business_private.event_availability(e)in('accepting','closed')and e.lifecycle='planned'and(e.operations->>'endAt')::timestamptz>now()then
  if(e.operations->>'capacity'is not null and(select count(*)from business_private.event_registrations where event_id=e.id and status='confirmed')>=(e.operations->>'capacity')::int)or(r.invite_id is not null and not exists(select from business_private.event_invites where id=r.invite_id and revoked_at is null))then raise exception'No eligible place available'using errcode='22023';end if;update business_private.event_registrations set status='confirmed',version=version+1 where id=r.id;
 elsif p_action='cancel'and r.status in('confirmed','waitlisted')then update business_private.event_registrations set status='cancelled',version=version+1 where id=r.id;update business_private.event_tickets set state='revoked'where registration_id=r.id and state='issued';else raise exception'Unsupported registration action'using errcode='22023';end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.registration_changed','event_registration',r.id::text,jsonb_build_object('action',p_action,'reasonReference',p_reason));end;$$;
create function public.record_event_payment(p_id uuid,p_version int,p_confirmed boolean,p_amount bigint,p_evidence text)returns void language plpgsql security definer set search_path=''as $$declare r business_private.event_registrations;begin perform business_private.require_permission('registrations.read');perform business_private.require_permission('registrations.manage');perform business_private.require_permission('events.operations.manage');select * into r from business_private.event_registrations where id=p_id for update;if not found or r.version is distinct from p_version then raise exception'Registration changed'using errcode='PT409';end if;if not r.fee_required or r.status<>'confirmed'or p_confirmed is null or p_amount is distinct from r.fee_xaf or not business_private.project_text(p_evidence,1,240)then raise exception'Exact physical payment evidence required'using errcode='22023';end if;
 insert into business_private.event_payment_checks(registration_id,confirmed,amount_xaf,evidence,actor_id)values(r.id,p_confirmed,p_amount,p_evidence,auth.uid());update business_private.event_registrations set version=version+1 where id=r.id;insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.payment_checked','event_registration',r.id::text,jsonb_build_object('confirmed',p_confirmed));end;$$;
create function public.issue_event_ticket(p_registration uuid,p_version int,p_ticket uuid,p_reference text,p_token_hex text,p_reissue boolean,p_reason text)returns jsonb language plpgsql security definer set search_path=''as $$declare r business_private.event_registrations;e business_private.events;t business_private.event_tickets;n int;begin perform business_private.require_permission('registrations.read');perform business_private.require_permission('registrations.manage');perform business_private.require_permission('events.operations.manage');select * into r from business_private.event_registrations where id=p_registration;if not found then raise exception'Ticket unavailable';end if;select * into e from business_private.events where id=r.event_id for update;select * into r from business_private.event_registrations where id=p_registration for update;
 if not business_private.event_eligible(r)or e.operations->>'format'not in('physical','hybrid')or e.lifecycle<>'planned'or(e.operations->>'endAt')::timestamptz<=now()then raise exception'Ticket eligibility denied'using errcode='42501';end if;
 select * into t from business_private.event_tickets where registration_id=r.id and state='issued';if found and p_reissue is false then return jsonb_build_object('id',t.id,'version',t.version);end if;
 if r.version is distinct from p_version then raise exception'Registration changed'using errcode='PT409';end if;if p_reissue is null or(p_reissue and not business_private.project_text(p_reason,1,240))or exists(select from business_private.event_attendance where registration_id=r.id)or p_ticket is null or p_reference is null or p_reference!~'^BWT-[a-f0-9]{32}$'or p_token_hex is null or p_token_hex!~'^[a-f0-9]{64}$'then raise exception'Invalid ticket operation'using errcode='22023';end if;
 select coalesce(max(version),0)+1 into n from business_private.event_tickets where registration_id=r.id;
 if n>1 and not p_reissue then raise exception'Explicit reissue required'using errcode='22023';end if;update business_private.event_tickets set state='revoked'where registration_id=r.id and state='issued';insert into business_private.event_tickets(id,registration_id,event_id,reference,version,token_hash,snapshot,actor_id)values(p_ticket,r.id,e.id,p_reference,n,decode(p_token_hex,'hex'),jsonb_build_object('templateVersion',1,'eventName',e.public_content->>'title','participantName',r.full_name,'startAt',e.operations->>'startAt','endAt',e.operations->>'endAt','timeZone',e.operations->>'timeZone','venue',e.operations->>'venue','reference',p_reference),auth.uid());update business_private.event_registrations set version=version+1 where id=r.id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.ticket_issued','event_ticket',p_ticket::text,jsonb_build_object('eventId',e.id,'version',n,'reissue',p_reissue));return jsonb_build_object('id',p_ticket,'version',n);end;$$;
create function business_private.event_ticket_document(p_id uuid)returns jsonb language plpgsql stable set search_path=''as $$declare t business_private.event_tickets;r business_private.event_registrations;begin select * into t from business_private.event_tickets where id=p_id and state='issued';if not found then raise exception'Ticket unavailable'using errcode='42501';end if;select * into r from business_private.event_registrations where id=t.registration_id;if not business_private.event_eligible(r)then raise exception'Ticket unavailable'using errcode='42501';end if;return jsonb_build_object('id',t.id,'version',t.version,'tokenHash',encode(t.token_hash,'hex'),'snapshot',t.snapshot,'issuedAt',t.issued_at);end;$$;
create function public.get_staff_event_ticket(p_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$begin perform business_private.require_permission('registrations.read');perform business_private.require_permission('documents.export');insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'event.ticket_download_authorized','event_ticket',p_id::text);return business_private.event_ticket_document(p_id);end;$$;
create function public.read_event_receipt(p_receipt_hex text,p_code_hex text,p_invite uuid,p_access_hex text,p_pdf boolean default false)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare r business_private.event_registrations;e business_private.events;t business_private.event_tickets;i business_private.event_invites;verified boolean:=false;
begin
 if p_receipt_hex is null or p_receipt_hex!~'^[a-f0-9]{64}$'then raise exception'Receipt unavailable'using errcode='42501';end if;
 select * into r from business_private.event_registrations where receipt_hash=decode(p_receipt_hex,'hex')and receipt_expires_at>now();if not found then raise exception'Receipt unavailable'using errcode='42501';end if;
 if p_code_hex is not null and p_code_hex~'^[a-f0-9]{64}$'then verified:=coalesce(r.portal_code_hash=decode(p_code_hex,'hex'),false);end if;
 if not verified and r.invite_id is not null and p_invite=r.invite_id then i:=business_private.event_guest(p_invite,p_access_hex);verified:=i.event_id=r.event_id;end if;
 if not verified then raise exception'Recipient verification required'using errcode='42501';end if;
 if r.invite_id is not null and not exists(select from business_private.event_invites where id=r.invite_id and revoked_at is null)then raise exception'Eligibility revoked'using errcode='42501';end if;
 select * into e from business_private.events where id=r.event_id;select * into t from business_private.event_tickets where registration_id=r.id and state='issued';if p_pdf then return business_private.event_ticket_document(t.id);end if;
 return jsonb_build_object('reference',r.reference,'event',r.event_snapshot,'participantName',r.full_name,'status',r.status,'paymentCleared',business_private.event_paid(r),'ticketAvailable',t.id is not null and business_private.event_eligible(r),'joiningUrl',case when business_private.event_eligible(r)then e.operations->'joiningUrl'else null end,'checkedIn',exists(select from business_private.event_attendance where registration_id=r.id));
end;$$;
create function business_private.resolve_event_ticket(p_event uuid,p_token_hex text,p_reference text)returns business_private.event_tickets language plpgsql stable set search_path=''as $$declare t business_private.event_tickets;r business_private.event_registrations;e business_private.events;begin
 select * into e from business_private.events where id=p_event;if not found or e.lifecycle<>'planned'or(e.operations->>'startAt')::timestamptz>now()or(e.operations->>'endAt')::timestamptz<=now()then raise exception'Check-in unavailable'using errcode='42501';end if;
 if p_reference is not null then if p_reference!~'^BWT-[a-f0-9]{32}$'or p_token_hex is not null then raise exception'Invalid ticket'using errcode='42501';end if;select * into t from business_private.event_tickets where event_id=p_event and reference=p_reference and state='issued';else if p_token_hex is null or p_token_hex!~'^[a-f0-9]{64}$'then raise exception'Invalid ticket'using errcode='42501';end if;select * into t from business_private.event_tickets where event_id=p_event and token_hash=decode(p_token_hex,'hex')and state='issued';end if;
 if not found then raise exception'Invalid ticket'using errcode='42501';end if;select * into r from business_private.event_registrations where id=t.registration_id;if not business_private.event_eligible(r)then raise exception'Invalid ticket'using errcode='42501';end if;return t;end;$$;
create function public.verify_event_ticket(p_event uuid,p_token_hex text,p_reference text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare t business_private.event_tickets;begin perform business_private.require_permission('events.checkin');t:=business_private.resolve_event_ticket(p_event,p_token_hex,p_reference);return jsonb_build_object('participantName',t.snapshot->>'participantName','ticketReference',t.reference,'status',case when exists(select from business_private.event_attendance where registration_id=t.registration_id)then'already_checked_in'else'eligible'end);end;$$;
create function public.check_in_event_ticket(p_event uuid,p_token_hex text,p_reference text)returns jsonb language plpgsql security definer set search_path=''as $$declare t business_private.event_tickets;target uuid;begin perform business_private.require_permission('events.checkin');perform pg_advisory_xact_lock(42047,1);perform 1 from business_private.events where id=p_event for update;
 t:=business_private.resolve_event_ticket(p_event,p_token_hex,p_reference);perform 1 from business_private.event_registrations where id=t.registration_id for update;t:=business_private.resolve_event_ticket(p_event,p_token_hex,p_reference);
 insert into business_private.event_attendance(registration_id,event_id,ticket_id,actor_id)values(t.registration_id,p_event,t.id,auth.uid())on conflict(registration_id)do nothing returning registration_id into target;
 if target is not null then insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'event.checked_in','event_registration',target::text,jsonb_build_object('eventId',p_event));end if;
 return jsonb_build_object('participantName',t.snapshot->>'participantName','ticketReference',t.reference,'status',case when target is null then'already_checked_in'else'checked_in'end);end;$$;
create function public.list_event_attendance(p_event uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('events.checkin');return(select coalesce(jsonb_agg(jsonb_build_object('participantName',t.snapshot->>'participantName','ticketReference',t.reference,'at',a.checked_at)order by a.checked_at),'[]'::jsonb)from business_private.event_attendance a join business_private.event_tickets t on t.id=a.ticket_id where a.event_id=p_event);end;$$;
-- Explicit function grants: no generic CRUD/private-schema exposure.
