do $$declare f record;begin for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('list_staff_events','list_event_assets','save_event_copy','configure_event','publish_event','create_event_invite','revoke_event_invite','list_event_invites','list_event_registrations','change_event_registration','record_event_payment','authorize_event_portal','issue_event_ticket','get_staff_event_ticket','verify_event_ticket','check_in_event_ticket','list_event_attendance')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.sig);execute format('grant execute on function %s to authenticated',f.sig);end loop;end;$$;
