grant execute on function public.claim_private_event(text,text,text,text,text,text),public.read_private_event(uuid,text),public.submit_event_registration(jsonb,text,text,text,text,text,text,text,text,uuid,text),public.read_event_receipt(text,text,uuid,text,boolean)to service_role;
